// Generates the native copies of the CSS named color map from
// src/utils/cssNamedColors.json. Run with `yarn generate:colors`.
const { readFileSync, writeFileSync } = require('node:fs');
const path = require('node:path');

const ROOT = path.join(__dirname, '..');
const SOURCE = path.join(ROOT, 'src/utils/cssNamedColors.json');
const IOS_OUTPUT = path.join(ROOT, 'ios/extensions/CSSNamedColors.generated.h');
const ANDROID_OUTPUT = path.join(
  ROOT,
  'android/src/main/java/com/swmansion/enriched/common/parser/CSSNamedColors.kt'
);

const HEADER =
  '// AUTO-GENERATED by scripts/generate-css-colors.js. Do not edit.\n' +
  '// Source of truth: src/utils/cssNamedColors.json\n';

const entries = Object.entries(JSON.parse(readFileSync(SOURCE, 'utf8')));

// Keys and values are emitted verbatim into ObjC/Kotlin string literals, so
// make sure nothing that would need escaping ever gets through.
for (const [name, hex] of entries) {
  if (!/^[a-z]+$/.test(name) || !/^#[0-9A-F]{8}$/.test(hex)) {
    throw new Error(`Invalid CSS named color entry: ${name} -> ${hex}`);
  }
}

function generateIosColorMap() {
  return `${HEADER}
// Only meant to be included by ColorExtension.mm.
#pragma once

#import <Foundation/Foundation.h>

static NSDictionary<NSString *, NSString *> *getNamedHexColors(void) {
  static NSDictionary<NSString *, NSString *> *namedColorHexes = nil;
  static dispatch_once_t onceToken;
  dispatch_once(&onceToken, ^{
    namedColorHexes = @{
${entries.map(([name, hex]) => `      @"${name}" : @"${hex}",`).join('\n')}
    };
  });
  return namedColorHexes;
}
`;
}

function generateAndroidColorMap() {
  return `${HEADER}
package com.swmansion.enriched.common.parser

internal val CSS_NAMED_COLORS: Map<String, String> =
  mapOf(
${entries.map(([name, hex]) => `    "${name}" to "${hex}",`).join('\n')}
  )
`;
}

writeFileSync(IOS_OUTPUT, generateIosColorMap());
writeFileSync(ANDROID_OUTPUT, generateAndroidColorMap());
